enum Transport { case webSocket, sse, polling, push }
func transport(for need: Need) -> Transport {
    switch need {
    case .liveBids: return .webSocket
    case .priceOnly: return .sse
    case .occasional: return .polling
    case .backgroundHint: return .push
    }
}
print(transport(for: .liveBids))
print(transport(for: .priceOnly))
print(transport(for: .occasional))
print(transport(for: .backgroundHint))

Вывод webSocket, sse, polling, push. Это явно заданная политика выбора, а не подключение к оборудованию.

import Foundation
struct StockUpdate {
    let itemID, revision, available: Int
}
protocol StockSource {
    func receive() async throws -> StockUpdate?
}
struct StockState {
    let itemID: Int
    var revision = 0
    var available = 0
    mutating func apply(_ value: StockUpdate) {
        guard value.itemID == itemID, value.revision > revision else { return }
        revision = value.revision
        available = value.available
    }
}
func follow(
    source: any StockSource, state: inout StockState
) async throws {
    while let value = try await source.receive() {
        try Task.checkCancellation()
        state.apply(value)
    }
}

Новый элемент — полный остаток товара. Более позднее старое сообщение не откатывает количество, другая сущность игнорируется.
